(async()=>{
  const r={}, w=ms=>new Promise(s=>setTimeout(s,ms));
  const b=[...document.querySelectorAll('button,a')].find(el=>/Entrar a MOS/i.test(el.textContent||''));
  if(b)b.click(); await w(5000);
  // el purgante recarga la pagina al detectar version nueva. Ojo: MOS es un const global,
  // NO vive en window, y leerlo en zona muerta tira TDZ incluso con typeof -> try/catch.
  const listo = () => { try { return !!MOS && typeof MOS.curvaOverlay === 'function'; } catch(_) { return false; } };
  for(let i=0;i<50 && !listo();i++){ await w(600); }
  r.appLista = listo();
  if(!r.appLista) return r;
  try{ r.version=(await fetch('https://levo19.github.io/MOS/version.json?b='+Date.now()).then(x=>x.json())).version }catch(_){}
  window._paso2Filas=[{nombre:'GLUTAMATO 1KG',precioActual:14.5,x:{idCanonico:'IDPRO0000035',descripcion:'GLUTAMATO 1KG',costoNuevo:12.1}}];
  try{ await MOS.curvaOverlay(0) }catch(e){ r.err=String(e) }
  await w(8000);
  const ov=document.getElementById('curvaOverlay'); r.overlay=!!ov; if(!ov) return r;
  const st=ov.querySelector('.cov-stage'), cv=document.getElementById('covCanvas');
  r.stage = st ? Math.round(st.getBoundingClientRect().width)+'x'+Math.round(st.getBoundingClientRect().height) : 'NO';
  r.viewport = window.innerWidth+'x'+window.innerHeight;
  r.canvasCSS = cv ? Math.round(cv.getBoundingClientRect().width)+'x'+Math.round(cv.getBoundingClientRect().height) : 'NO';
  r.titulo=(document.getElementById('covTit')||{}).textContent;
  r.chips=[...ov.querySelectorAll('.cov-chip')].map(e=>e.textContent.trim());
  r.alarma=(ov.querySelector('.cov-alarma')||{}).textContent||'(sin alarma)';
  r.latido=!!ov.querySelector('.cov-live');
  r.tabs=[...ov.querySelectorAll('.cov-tab')].map(e=>e.textContent.replace(/[  ]+/g,' ').trim());
  r.paneInicial=(ov.querySelector('.cov-panes')||{}).textContent.slice(0,60);
  // pestaña de ingresos
  const t=[...ov.querySelectorAll('.cov-tab')];
  if(t[1]){ t[1].click(); await w(600); r.paneIngresos=ov.querySelectorAll('.cov-ing-r').length; }
  if(t[2]){ t[2].click(); await w(600); r.paneAnulados=ov.querySelectorAll('.cov-anul-r').length; }
  // ⛶ expandir
  const hAntes=cv.getBoundingClientRect().height;
  MOS._curvaDock(); await w(900);
  r.canvasTrasExpandir=Math.round(cv.getBoundingClientRect().width)+'x'+Math.round(cv.getBoundingClientRect().height);
  r.crecio = cv.getBoundingClientRect().height > hAntes;
  r.dockOculto = ov.classList.contains('cov-solo');
  MOS._curvaDock(); await w(700);
  r.vuelve = !ov.classList.contains('cov-solo');
  // abrir un punto desde la pestaña de registros
  t[0].click(); await w(500);
  const reg=ov.querySelector('.cov-reg');
  if(reg){ reg.click(); await w(4000);
    const c=document.getElementById('curvaCard');
    r.cardAbre=!!c; if(c) r.cardGuia=(c.querySelector('.cvf-guia-prov')||{}).textContent; }
  return r;
})()
